//! #664: CommonJS export writes in a file that also has a program-level ESM export (`export ..`) are no
//! authoritative export claim (in Node such a file is an ES module and `exports`/`module` do not exist), so no
//! consumer form binds Exact `import_member` through them. The matrix is
//! `tests/fixtures/js_mixed_esm_cjs/matrix.jsonl` (generated by the script recorded in the PR): CJS producer form
//! x ESM-export spelling x consumer form. `refuse` rows (mixed producer) pin `drop UnknownName`; every one is
//! Exact `import_member` on base f4c6297d. `control` rows (pure CJS, pure ESM, an `export` only inside a
//! namespace, the ESM side of a mixed file) pin the unchanged outcome.
use super::js_cjs_named_fn_expr_test::{outcome, Row};
use super::js_relative_extension_test::graph;

const MATRIX: &str = include_str!("../fixtures/js_mixed_esm_cjs/matrix.jsonl");
/// Round 1 fold: focused consumer-route (barrel, alias chain, returned value) and ESM-spelling rows.
const FOCUS: &str = include_str!("../fixtures/js_mixed_esm_cjs/focus.jsonl");

fn rows() -> Vec<Row> {
    MATRIX
        .lines()
        .chain(FOCUS.lines())
        .map(|l| serde_json::from_str(l).expect("matrix row"))
        .collect()
}

fn actual(row: &Row) -> Vec<String> {
    let file = row.consumer_file.as_deref().unwrap_or("app.js");
    let producer = row.producer_file.as_deref().unwrap_or("m.js");
    let mut files: Vec<(&str, &str)> = vec![
        (producer, row.producer.as_str()),
        (file, row.consumer.as_str()),
    ];
    for (path, src) in row.extra.iter().flatten() {
        files.push((path.as_str(), src.as_str()));
    }
    outcome(&graph(&files), &row.callee, file)
}

#[test]
fn mixed_producer_matrix_holds() {
    let all = rows();
    assert!(all.len() >= 100, "matrix shrank to {} rows", all.len());
    let mut failures = Vec::new();
    for row in &all {
        let got = actual(row);
        if got != row.expect {
            failures.push(format!(
                "{} [{}]: expected {:?}, got {:?}",
                row.id, row.kind, row.expect, got
            ));
        }
        let exact = got.iter().any(|a| a.contains("Exact/import_member"));
        if row.kind == "refuse" && exact {
            failures.push(format!("{}: refuse row is Exact: {got:?}", row.id));
        }
    }
    assert!(
        failures.is_empty(),
        "{} rows:\n{}",
        failures.len(),
        failures.join("\n")
    );
}

/// The matrix keeps both polarities: mixed rows refuse, and controls keep an Exact edge somewhere per producer form.
#[test]
fn matrix_has_refuse_and_exact_controls() {
    let all = rows();
    for esm in [
        "export-const",
        "export-default",
        "export-braces",
        "export-star",
        "ts-export-equals",
    ] {
        assert!(
            all.iter()
                .any(|r| r.kind == "refuse" && r.id.contains(&format!("/{esm}/"))),
            "no refuse row for {esm}"
        );
    }
    for prod in ["decl-member", "decl-module-value", "expr-member"] {
        for group in ["m664-pure-cjs", "m664-ns-nested"] {
            assert!(
                all.iter()
                    .any(|r| r.id.starts_with(&format!("{group}/{prod}/"))
                        && r.expect.iter().any(|e| e.contains("Exact/import_member"))),
                "no Exact control for {group}/{prod}"
            );
        }
    }
    assert!(all.iter().any(|r| r.id.starts_with("m664-pure-esm/")
        && r.expect.iter().any(|e| e.contains("Exact/import_member"))));
    // Round 1 fold: consumer routes and ESM-spelling controls must stay present. Alias-chain and returned-value
    // rows have no Exact edge for a CommonJS producer even on base (spanless CJS exports), so they pin "unchanged".
    for needle in [
        "s1-barrel/star/mixed",
        "s1-barrel/named/mixed",
        "s1-barrel/default-reexport/mixed",
        "s1-alias/import-const-alias/mixed",
        "s1-alias/require-chain/mixed",
        "s1-returned/imported-helper-destructured/mixed",
        "s1-spelling/empty-export-braces/mixed",
        "s1-spelling/export-as-namespace/mixed",
        "s1-spelling/dts-producer/mixed",
        "s1-spelling/module-block-nested/control",
        "s1-spelling/import-only-producer/control",
    ] {
        assert!(all.iter().any(|r| r.id == needle), "missing row {needle}");
    }
    for group in [
        "s1-barrel/star",
        "s1-barrel/named",
        "s1-barrel/default-reexport",
    ] {
        let refused = all
            .iter()
            .any(|r| r.id == format!("{group}/mixed") && r.kind == "refuse");
        let control = all.iter().any(|r| {
            r.id == format!("{group}/pure-cjs")
                && r.expect.iter().any(|e| e.contains("Exact/import_member"))
        });
        assert!(
            refused && control,
            "{group}: refuse row or pure-CJS Exact control missing"
        );
    }
    for spelling in ["module-block-nested", "import-only-producer"] {
        assert!(
            all.iter()
                .any(|r| r.id.starts_with(&format!("s1-spelling/{spelling}/"))
                    && r.expect.iter().any(|e| e.contains("Exact/import_member"))),
            "{spelling} must stay an Exact control"
        );
    }
}
